SELECT COALESCE(SUM(income), 0)
FROM tax_record
WHERE userId = #{userId}
  AND taxYear = #{taxYear}
  AND taxMonth != 0
  AND isDelete = 0

SELECT COALESCE(SUM(insurance), 0)
FROM tax_record
WHERE userId = #{userId}
  AND taxYear = #{taxYear}
  AND taxMonth != 0
  AND isDelete = 0

SELECT COALESCE(SUM(deduct), 0)
FROM tax_record
WHERE userId = #{userId}
  AND taxYear = #{taxYear}
  AND taxMonth != 0
  AND isDelete = 0

SELECT COALESCE(SUM(taxAmount), 0)
FROM tax_record
WHERE userId = #{userId}
  AND taxYear = #{taxYear}
  AND taxMonth != 0
  AND isDelete = 0

SELECT * FROM tax_record
WHERE userId = #{userId}
  AND taxYear = #{taxYear}
  AND isDelete = 0
ORDER BY taxMonth ASC
